Widget _hero(BuildContext c,AppState s)=>Card(color:Theme.of(c).colorScheme.primaryContainer,child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[CircleAvatar(radius:34,backgroundColor:Theme.of(c).colorScheme.primary,child:const Icon(Icons.auto_awesome,color:Colors.white,size:32)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('مستوى ${s.level} • ${s.xp} XP',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:6),Text('أكملت ${(s.learningProgress*100).round()}% من الدروس و${(s.taskProgress*100).round()}% من المهام.'),const SizedBox(height:10),LinearProgressIndicator(value:s.learningProgress,minHeight:8,borderRadius:BorderRadius.circular(8))]))]));
