void _addSubject(BuildContext c){final x=TextEditingController();showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('إضافة مادة'),content:TextField(controller:x,decoration:const InputDecoration(labelText:'اسم المادة')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إلغاء')),FilledButton(onPressed:(){if(x.text.trim().isNotEmpty)AppState.instance.addSubject(x.text.trim());Navigator.pop(c);},child:const Text('حفظ'))]));}
void _addTask(BuildContext c,AppState s){final title=TextEditingController();String subject=s.subjects.isEmpty?'مذاكرة عامة':s.subjects.first.name;showDialog(context:c,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('إضافة مهمة'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'المهمة')),const SizedBox(height:10),DropdownButtonFormField<String>(value:subject,items:s.subjects.map((x)=>DropdownMenuItem(value:x.name,child:Text(x.name))).toList(),onChanged:(v)=>set(()=>subject=v!),decoration:const InputDecoration(labelText:'المادة'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إلغاء')),FilledButton(onPressed:(){if(title.text.trim().isNotEmpty)s.addTask(title.text.trim(),subject,dueDate:DateTime.now());Navigator.pop(c);},child:const Text('إضافة'))])));}
void _startSession(BuildContext c,AppState s){Navigator.of(c).push(MaterialPageRoute(builder:(_)=>const _SessionPage()));}
