void _addSchedule(BuildContext c,AppState s){final t=TextEditingController();showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('إضافة جلسة للخطة'),content:TextField(controller:t,decoration:const InputDecoration(labelText:'عنوان الجلسة')),actions:[FilledButton(onPressed:(){if(t.text.trim().isNotEmpty)s.addSchedule(t.text.trim(),s.subjects.isEmpty?'عام':s.subjects.first.name,DateTime.now().add(const Duration(hours:1)),45);Navigator.pop(c);},child:const Text('إضافة'))]));}
