class _SessionPage extends StatefulWidget{const _SessionPage();@override State<_SessionPage> createState()=>_SessionPageState();}
class _SessionPageState extends State<_SessionPage>{int sec=25*60;bool run=false;@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:const Text('جلسة مذاكرة')),body:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('${sec~/60}:${(sec%60).toString().padLeft(2,'0')}',style:const TextStyle(fontSize:56,fontWeight:FontWeight.w900)),const SizedBox(height:20),FilledButton.icon(onPressed:run?null:(){setState(()=>run=true);_tick();},icon:const Icon(Icons.play_arrow),label:const Text('بدء جلسة 25 دقيقة')),const SizedBox(height:10),OutlinedButton(onPressed:(){setState(()=>sec=25*60);},child:const Text('إعادة'))]));}void _tick(){Future.delayed(const Duration(seconds:1),(){if(!mounted||!run)return;if(sec>0){setState(()=>sec--);_tick();}else{setState(()=>run=false);AppState.instance.addSession('جلسة عامة',25);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('انتهت الجلسة 🎉 حان وقت الراحة 5 دقائق.')));}});} }
